// people.js - what every modelled person in the game is made of: the part geometries (src/people_geo.js, generated by tools/people/geo.py),
// the clothing atlas (assets/people/cloth_atlas.webp, painted by tools/people/atlas.py) and the one material that draws them.
//
// The atlas: RGB is the art, alpha says who colours it. 1 = the wearer's dye (the art's brightness x his colour), 0.5 = his second colour (skin on
// bodies and arms, hair on heads, a veil or lining on headwear), 0 = the art's own colour (fur, gold, leather, linen, eyes).
// A part's UVs are pixels inside its own atlas cell; the cell's corner comes per instance (crowd) or per material (single figures), so the same
// tunic mesh wears any tunic cell.
//
// Parts (metres): bodies stand on y = 0 with the shoulder line at 1.40 ('tunic', 'gown', 'robe'); 'head' is centred on the middle of the skull;
// 'arm' hangs from the origin, 1 long; headwear is in the head's own space. Bodies and heads carry a "fat" delta (attribute aFat).
import * as THREE from 'three';
import { PEOPLE_GEO, PEOPLE_LAYOUT } from './people_geo.js';
import { GFX } from './gfx.js';
import { headFor } from './people_heads.js';

export const LAYOUT = PEOPLE_LAYOUT;
const W = LAYOUT.W, H = LAYOUT.H;
const bytes = (s) => { const b = atob(s), a = new Uint8Array(b.length); for (let i = 0; i < b.length; i++) a[i] = b.charCodeAt(i); return a; };
export const b64 = { u8: bytes, i8: (s) => new Int8Array(bytes(s).buffer), i16: (s) => new Int16Array(bytes(s).buffer), u16: (s) => new Uint16Array(bytes(s).buffer) };

const cache = new Map();
/** The geometry of a part: position, normal, uv (atlas units, relative to its cell's corner), aSh (baked shade), aFat (the heavy figure's delta). */
export function partGeo(name) {
  if (cache.has(name)) return cache.get(name);
  const d = PEOPLE_GEO[name]; if (!d) throw new Error('no such part: ' + name);
  const n = d.n, p = b64.i16(d.p), nm = b64.i8(d.nm), uv = b64.u16(d.uv), g = new THREE.BufferGeometry();
  const P = new Float32Array(n * 3), N = new Float32Array(n * 3), U = new Float32Array(n * 2), F = new Float32Array(n * 3), S = new Float32Array(n);
  for (let i = 0; i < n * 3; i++) { P[i] = p[i] / 32767 * d.s; N[i] = nm[i] / 127; }
  for (let i = 0; i < n; i++) { U[i * 2] = uv[i * 2] / 65535 * d.uvs / W; U[i * 2 + 1] = -uv[i * 2 + 1] / 65535 * d.uvs / H; }
  if (d.d) { const dd = b64.i8(d.d); for (let i = 0; i < n * 3; i++) F[i] = dd[i] / 127 * d.ds; }
  if (d.c) { const c = b64.u8(d.c); for (let i = 0; i < n; i++) S[i] = c[i] / 255; } else S.fill(1);
  g.setAttribute('position', new THREE.BufferAttribute(P, 3)); g.setAttribute('normal', new THREE.BufferAttribute(N, 3)); g.setAttribute('uv', new THREE.BufferAttribute(U, 2));
  g.setAttribute('aFat', new THREE.BufferAttribute(F, 3)); g.setAttribute('aSh', new THREE.BufferAttribute(S, 1));
  g.setIndex(new THREE.BufferAttribute(b64.u16(d.i), 1)); g.userData.tris = g.index.count / 3;
  cache.set(name, g); return g;
}
/** A copy that shares the vertex data but can take its own per-instance attributes or be moved (translate / scale bake a new position array). */
export function shareGeo(g) { const c = new THREE.BufferGeometry(); for (const k in g.attributes) c.setAttribute(k, g.attributes[k]); c.setIndex(g.index); return c; }
/** A part scaled and moved for a jointed figure (its own position, normal and fat arrays). */
export function fitGeo(name, sx, sy, sz, tx = 0, ty = 0, tz = 0) {
  const g = partGeo(name).clone(); g.scale(sx, sy, sz); const f = g.attributes.aFat; for (let i = 0; i < f.count; i++) f.setXYZ(i, f.getX(i) * sx, f.getY(i) * sy, f.getZ(i) * sz);
  g.translate(tx, ty, tz); return g;
}

// ------------------------------------------------------------------------------------------------ atlas cells
/** The corner of a cell as the shader wants it: [u, v] of its top-left. */
const corner = (at) => [at[0] / W, 1 - at[1] / H];
export const GARMENTS = LAYOUT.garments.map((g, i) => Object.assign({ i, uv: corner(g.at) }, g));
export const garment = (id) => GARMENTS.find(g => g.id === id) || GARMENTS[0];
export const faceUV = (id) => corner(LAYOUT.faces[id] || LAYOUT.faces.m_plain);
export const patchUV = (id) => corner(LAYOUT.patches[id] || LAYOUT.patches.spare);

let atlas = null;
/** The clothing atlas (half size on the low tier). A flat grey stands in until the picture has arrived: every figure is then plainly his own colour. */
export function atlasTexture() {
  if (atlas) return atlas;
  const cv = document.createElement('canvas'); cv.width = cv.height = 2; const g = cv.getContext('2d'); g.fillStyle = 'rgb(186,186,186)'; g.fillRect(0, 0, 2, 2);
  const t = atlas = new THREE.Texture(cv); t.colorSpace = THREE.SRGBColorSpace; t.flipY = true; t.anisotropy = Math.min(4, GFX.aniso || 4); t.needsUpdate = true; t.generateMipmaps = true; t.minFilter = THREE.LinearMipmapLinearFilter;
  const im = new Image(); im.onload = () => { t.dispose(); t.image = im; t.needsUpdate = true; };      // (dispose: the stand-in's storage is the wrong size) im.onerror = () => console.warn('[people] the clothing atlas did not load');
  im.src = new URL(`../assets/people/cloth_atlas${GFX.tier === 'low' ? '_512' : ''}.webp`, import.meta.url).href;
  return t;
}

// ------------------------------------------------------------------------------------------------ the material
const LGAIN = (1 / Math.pow((186 / 255 + 0.055) / 1.055, 2.4)).toFixed(4);      // a dyed cloth painted at grey 186 comes out as exactly the wearer's colour
function patch(mat, instanced) {
  mat.defines = Object.assign(mat.defines || {}, instanced ? { PEOPLE_INST: '' } : {});
  const U = mat.userData; if (!instanced) { U.uPar = { value: new THREE.Vector4(0, 1, 0, 0) }; U.uCol2 = { value: new THREE.Vector4(0.8, 0.6, 0.45, 1) }; }
  mat.onBeforeCompile = (sh) => {
    if (!instanced) { sh.uniforms.uPar = U.uPar; sh.uniforms.uCol2 = U.uCol2; }
    sh.vertexShader = sh.vertexShader
      .replace('#include <common>', `#include <common>
        attribute vec3 aFat; attribute float aSh; varying vec4 vCol2; varying float vSh;
        #ifdef PEOPLE_INST
          attribute vec4 iPar; attribute vec4 iCol2; attribute float iBend;      // iBend: the elbow (arms only, radians; 0 elsewhere, an unbound attribute reads 0)
          #define PPAR iPar
          #define PCOL2 iCol2
        #else
          uniform vec4 uPar; uniform vec4 uCol2;
          #define PPAR uPar
          #define PCOL2 uCol2
        #endif`)
      .replace('#include <uv_vertex>', '#include <uv_vertex>\n vMapUv = uv + PPAR.xy;')
      .replace('#include <beginnormal_vertex>', `#include <beginnormal_vertex>
        #ifdef PEOPLE_INST
        if (iBend != 0.0) {      // the elbow, normals: the upper arm turned by the bend, the forearm by minus the bend, blended across the joint (see the positions below)
          float bw = smoothstep(0.38, 0.62, clamp(-position.y, 0.0, 1.0)), bc = cos(iBend), bs = sin(iBend);
          vec3 nu = vec3(objectNormal.x, objectNormal.y * bc - objectNormal.z * bs, objectNormal.y * bs + objectNormal.z * bc);
          vec3 nl = vec3(objectNormal.x, objectNormal.y * bc + objectNormal.z * bs, -objectNormal.y * bs + objectNormal.z * bc);
          objectNormal = normalize(mix(nu, nl, bw));
        }
        #endif`)
      .replace('#include <begin_vertex>', `#include <begin_vertex>
        transformed += aFat * PPAR.z; vCol2 = PCOL2; vSh = aSh;
        #ifdef PEOPLE_INST
        if (iBend != 0.0) {      // an ELBOW. The arm is a unit tube along -y (the matrix scales it to the arm's length): the upper half is turned about the shoulder by the bend (elbow back, z is the
          // figure's front), the lower half about the elbow by minus the bend, and both are stretched by 1/cos so the hand stays exactly where the straight arm's hand was (callers that put
          // a hat or a banner in the hand, and the claps that meet, need no change). K: the matrix scales z (the girth) about 1.5x more than y (the length), so the turn is done in metres.
          float eu = clamp(-transformed.y, 0.0, 1.0), ew = smoothstep(0.38, 0.62, eu), ec = cos(iBend), es = sin(iBend), esc = 1.0 / ec, K = 1.5;
          vec3 ep = vec3(transformed.x, transformed.y, transformed.z * K);
          vec3 pu = vec3(ep.x, ep.y * esc, ep.z); pu = vec3(pu.x, pu.y * ec - pu.z * es, pu.y * es + pu.z * ec);
          vec3 eq = vec3(ep.x, (ep.y + 0.5) * esc, ep.z), elb = vec3(0.0, -0.5, -0.5 * es * esc);
          vec3 pl = elb + vec3(eq.x, eq.y * ec + eq.z * es, -eq.y * es + eq.z * ec);
          ep = mix(pu, pl, ew); transformed = vec3(ep.x, ep.y, ep.z / K);
        }
        #endif
        if (PPAR.w > 0.0) {      // seated: the figure folds at the hip (0.62 of the shoulder height), the lap comes forward
          float hip = 0.62, k = transformed.y / hip;
          if (k < 1.0) { transformed.z += PPAR.w * 0.36 * min(1.0, (1.0 - k) / 0.42); transformed.y *= 1.0 - PPAR.w; } else transformed.y -= hip * PPAR.w;
        }`);
    sh.fragmentShader = sh.fragmentShader
      .replace('#include <common>', '#include <common>\n varying vec4 vCol2; varying float vSh;')
      .replace('#include <map_fragment>', 'vec4 pTex = texture2D( map, vMapUv );')
      .replace('#include <color_fragment>', `#include <color_fragment>
        float pl = min(dot(pTex.rgb, vec3(0.2126, 0.7152, 0.0722)) * ${LGAIN}, 1.7), pw1 = smoothstep(0.62, 0.9, pTex.a), pw2 = (1.0 - pw1) * smoothstep(0.15, 0.4, pTex.a);
        diffuseColor.rgb = mix(mix(pTex.rgb * vCol2.a, vCol2.rgb * pl, pw2), diffuseColor.rgb * pl, pw1) * vSh;`);
  };
  return mat;
}
let crowdMat = null;
/** The crowd's material: instanced. Each InstancedMesh's geometry needs iPar (cell u, cell v, fat, seated) and iCol2 (second colour rgb, light) per instance. */
export function crowdMaterial() { return crowdMat || (crowdMat = patch(new THREE.MeshStandardMaterial({ map: atlasTexture(), roughness: 0.92, envMapIntensity: 0.25 }), true)); }

const _c = new THREE.Color();
/**
 * The material of one part of a single figure: colour = the dye, c2 = the second colour, cell = [u, v] of the atlas cell, fat = -0.4 (thin) .. 1 (heavy).
 * Lambert, like the other cheap figures (kind: 'standard' for the knight's head). Materials are shared by key.
 */
const single = new Map();
export function partMaterial(color, c2 = '#e0ac84', cell = [0, 1], fat = 0, kind = 'lambert') {
  const key = [color, c2, cell[0], cell[1], fat, kind].join('|'); if (single.has(key)) return single.get(key);
  const m = patch(kind === 'standard' ? new THREE.MeshStandardMaterial({ map: atlasTexture(), color, roughness: 0.85, envMapIntensity: 0.4 }) : new THREE.MeshLambertMaterial({ map: atlasTexture(), color }), false);
  _c.set(c2); m.userData.uCol2.value.set(_c.r, _c.g, _c.b, 1); m.userData.uPar.value.set(cell[0], cell[1], fat, 0);
  single.set(key, m); return m;
}
/** The same patch on a material of your own (the knight's head, with its own face sheet as the map). Returns the material; set userData.uCol2 / uPar. */
export const tintPatch = (mat) => patch(mat, false);

// ------------------------------------------------------------------------------------------------ the jointed figure (heralds, judges, flagmen, the band, the sellers, your men)
// The cheap figures of src/ceremony.js and src/retinue_field.js are groups turned at the hip, the shoulders and the neck. These are the modelled parts
// cut to those joints: torso (origin at the hips, 0.85 up; tunic to mid-thigh), leg (hangs 0.85 from the hip), arm (hangs 0.6 from the shoulder to the
// middle of the hand), head (centred; the callers put it 0.12 above the neck joint), hat (a chaperon, in the head's space).
let FIG = null;
export const ARM_AT = [0.2, 0.535];      // the shoulder joint on the torso (x, y)
export function figure() {
  return FIG || (FIG = { torso: fitGeo('tunic_top_hi', 1.06, 1.06, 1.06, 0, -0.88 * 1.06, 0), leg: fitGeo('leg_hi', 1, 0.85 / 0.7, 1, -0.085, -0.85, 0), arm: fitGeo('arm_npc_hi', 1.05, 0.65, 1.05),
    head: partGeo('head_mid'), hat: partGeo('chaperon_hi'), cap: partGeo('feltcap_hi'), coif: partGeo('coif_hi'), hood: partGeo('hood_hi'), straw: partGeo('straw_hi'),
    robe: fitGeo('robe_npc_hi', 1.06, 1.06, 1.06, 0, -0.88 * 1.06, 0) });
}
// ------------------------------------------------------------------------------------------------ the elbow of the jointed figures
/** The triangles of `g` whose middle is above (up = true) or below y = cut, as their own geometry (vertices renumbered). Below the cut the geometry is moved so the elbow is its origin. */
function armHalf(g, cut, up) {
  const I = g.index.array, P = g.attributes.position, keep = [];
  for (let t = 0; t < I.length; t += 3) { const y = (P.getY(I[t]) + P.getY(I[t + 1]) + P.getY(I[t + 2])) / 3; if ((y >= cut) === up) keep.push(I[t], I[t + 1], I[t + 2]); }
  const map = new Map(), order = [], idx = keep.map((v) => { let n = map.get(v); if (n === undefined) { n = order.length; map.set(v, n); order.push(v); } return n; }), h = new THREE.BufferGeometry();
  for (const k in g.attributes) { const a = g.attributes[k], d = new a.array.constructor(order.length * a.itemSize); order.forEach((v, i) => { for (let c = 0; c < a.itemSize; c++) d[i * a.itemSize + c] = a.array[v * a.itemSize + c]; }); h.setAttribute(k, new THREE.BufferAttribute(d, a.itemSize)); }
  h.setIndex(idx); if (!up) h.translate(0, -cut, 0); return h;
}
/** A ball of the sleeve's own cell joined into the forearm (origin = the elbow): where the two halves turn against each other the outside of the bend opens a wedge, the ball fills it. Same geometry, no extra draw call. */
function elbowBall(low, r, ry) {
  const P = low.attributes.position; let k = 0, best = 9;      // a vertex of the forearm's top ring: its sleeve uv and shade
  for (let i = 0; i < P.count; i++) { const d = Math.abs(P.getY(i) + 0.03); if (d < best) { best = d; k = i; } }
  let u0 = 9, u1 = -9; for (let i = 0; i < P.count; i++) if (Math.abs(P.getY(i) - P.getY(k)) < 1e-4) { const x = low.attributes.uv.getX(i); u0 = Math.min(u0, x); u1 = Math.max(u1, x); }
  const s = new THREE.SphereGeometry(1, 10, 7), n = s.attributes.position.count, u = (u0 + u1) / 2, v = low.attributes.uv.getY(k), sh = low.attributes.aSh.getX(k);
  s.scale(r, ry, r); const sn = s.attributes.normal, base = P.count, A = {};
  for (const name in low.attributes) {
    const a = low.attributes[name], d = new Float32Array((base + n) * a.itemSize); d.set(a.array, 0);
    for (let i = 0; i < n; i++) {
      const o = (base + i) * a.itemSize;
      if (name === 'position') { d[o] = s.attributes.position.getX(i); d[o + 1] = s.attributes.position.getY(i); d[o + 2] = s.attributes.position.getZ(i); }
      else if (name === 'normal') { d[o] = sn.getX(i); d[o + 1] = sn.getY(i); d[o + 2] = sn.getZ(i); }
      else if (name === 'uv') { d[o] = u; d[o + 1] = v; } else if (name === 'aSh') d[o] = sh;
    }
    A[name] = new THREE.BufferAttribute(d, a.itemSize);
  }
  const I = Array.from(low.index.array), SI = s.index.array; for (let i = 0; i < SI.length; i++) I.push(base + SI[i]);
  const out = new THREE.BufferGeometry(); for (const name in A) out.setAttribute(name, A[name]); out.setIndex(I); return out;
}
const ARM_LEN = 0.65, ARM_ELBOW = 0.3;      // the arm part is 0.65 long (its hand ends there); the elbow is 0.3 from the shoulder
let ARM2 = null;
/**
 * An arm with an ELBOW, for every jointed figure (heralds, judges, flagmen, the band, your men, the stands' sellers...). It stands in for the one-piece arm mesh: a Group at the
 * shoulder (the callers turn their own shoulder group, `armL.add(D.armL)`, and hang what he holds at 0.6 below it) holding an upper arm and a forearm that are re-posed just
 * before they are drawn from how far that shoulder group has swung the arm forward or out: a little slack at rest, up to about 32 degrees as the arm is lifted (a raised flag, a
 * presented lance, a herald's scroll, a trumpet). The two halves lean in opposite directions (elbow back, forearm forward) and are stretched by 1/cos so the HAND STAYS EXACTLY
 * where the straight arm's hand was: nothing that is held, nothing that was posed, needs touching. `.material` reads (and sets) both halves, as it did on the old mesh.
 */
export function elbowArm(F, mat, shadow) {
  const a = ARM2 || (ARM2 = { up: armHalf(F.arm, -ARM_ELBOW, true), low: elbowBall(armHalf(F.arm, -ARM_ELBOW, false), 0.06, 0.06) });
  const g = new THREE.Group(), up = new THREE.Mesh(a.up, mat), low = new THREE.Mesh(a.low, mat);
  up.castShadow = low.castShadow = shadow; g.add(up, low);
  const l1 = ARM_ELBOW, l2 = ARM_LEN - ARM_ELBOW, set = () => {
    const p = g.parent, rx = p ? p.rotation.x : 0, rz = p ? p.rotation.z : 0;
    const t1 = 0.1 + 0.34 * Math.min(1, Math.max(0, -rx) / 2.2) + 0.12 * Math.min(1, Math.abs(rz)), t2 = Math.asin(l1 * Math.sin(t1) / l2), s = ARM_LEN / (l1 * Math.cos(t1) + l2 * Math.cos(t2));
    up.rotation.x = t1; up.scale.y = s; low.rotation.x = -t2; low.scale.y = s; low.position.set(0, -l1 * s * Math.cos(t1), -l1 * s * Math.sin(t1));
    up.updateMatrix(); low.updateMatrix(); up.matrixWorld.multiplyMatrices(g.matrixWorld, up.matrix); low.matrixWorld.multiplyMatrices(g.matrixWorld, low.matrix);
  };
  up.onBeforeRender = low.onBeforeRender = set;      // (the shoulder group's turn has been applied by now: scene.updateMatrixWorld ran first)
  up.frustumCulled = low.frustumCulled = false;
  Object.defineProperty(g, 'material', { get: () => up.material, set: (m) => { up.material = low.material = m; } });
  set(); return g;
}
const brighter = (c, k) => '#' + _c.set(c).multiplyScalar(k).getHexString();
/**
 * The dressed parts of one figure, as meshes to hang on its joints: { torso, legL, legR, armL, armR, head } (the hat, if any, is on the head).
 * o: coat (the tunic's dye), hose, skin, hair, garb (a tunic of the atlas: 'doublet', 'tunic_plain', 'tabard', ...), tab (a tabard in this colour over the coat),
 *    robe (a long robe of the atlas instead: 'robe_judge', 'houppelande_m', ...: no legs), hose2 (the other leg, parti-coloured), sleeve (a sleeve patch), face (a face cell), fat (-0.4..1), hat: { kind: 'hat' | 'cap' | 'coif' | 'hood' | 'straw', color }.
 */
export function dressFigure(o) {
  const F = figure(), skin = o.skin || '#e0ac84', fat = o.fat || 0, G = garment(o.tab ? 'tabard' : o.garb || 'doublet'), hoseCell = garment('doublet').uv;
  const M = (geo, mat, sh = true) => { const m = new THREE.Mesh(geo, mat); m.castShadow = sh; return m; };
  const leg = (c) => M(F.leg, partMaterial(brighter(c, 1.4), skin, hoseCell, fat * 0.5), false);      // (the doublet's hose is painted dark: lift the dye back to the colour asked for)
  const slv = patchUV(o.sleeve || 'sleeve_wool');
  const R = o.robe ? garment(o.robe) : null;      // a long robe instead of the short gown and hose (the marshal of the lists)
  const out = { torso: R ? M(F.robe, partMaterial(o.coat, skin, R.uv, fat)) : M(F.torso, partMaterial(o.tab || o.coat, skin, G.uv, fat)), legL: R ? null : leg(o.hose), legR: R ? null : leg(o.hose2 || o.hose), armL: elbowArm(F, partMaterial(o.coat, skin, slv, 0), false), armR: elbowArm(F, partMaterial(o.coat, skin, slv, 0), false),
    head: null };
  // the head: the figures the camera goes close to (o.close: the judges, the herald, the marshal, the flagmen, your men) get the knight's modelled head with its
  // hair and beard (src/people_heads.js) on the high and medium tiers; the rest, and everyone on the low tier, the lighter head with a painted face
  const KH = { m_young: 0, m_plain: 1, m_beard: 1, m_fullbeard: 2, m_old: 2, m_moustache: 3, m_dark: 4, m_tonsure: 5, m_fat: 5 };
  out.head = GFX.tier === 'low' || !o.close ? M(F.head, partMaterial(skin, o.hair || '#4a3524', faceUV(o.face || 'm_plain'), Math.max(0, fat)), false)
    : headFor(KH[o.face || 'm_plain'] ?? 1, 'm', fat > 0.45 ? 'heavy' : fat < -0.15 ? 'skinny' : 'medium', skin, o.hair || '#4a3524', !!o.hat);
  if (out.head.isGroup) { const w = new THREE.Group(); out.head.position.y = -0.035; w.add(out.head); out.head = w; }      // (this head has a neck of its own: it sits a little lower on the joint)
  if (o.hat) { const h = M(F[o.hat.kind] || F.hat, partMaterial(o.hat.color, '#e0d9c3', patchUV({ hat: 'chaperon', cap: 'feltcap' }[o.hat.kind] || o.hat.kind), 0), false); (out.head.isGroup ? out.head.children[0] : out.head).add(h); }      // (the hat rides the head)
  return out;
}
